CREATE TABLE engagements (_id TEXT PRIMARY KEY,workspaceId TEXT NOT NULL,client TEXT NOT NULL,name TEXT NOT NULL,createdAt INTEGER NOT NULL);
CREATE INDEX idx_engagements_workspace ON engagements(workspaceId);
CREATE TABLE obligationDocuments (_id TEXT PRIMARY KEY,workspaceId TEXT NOT NULL,engagementId TEXT NOT NULL,label TEXT NOT NULL,kind TEXT NOT NULL,body TEXT NOT NULL,contentHash TEXT NOT NULL,version INTEGER NOT NULL,supersedesId TEXT,createdAt INTEGER NOT NULL,UNIQUE(engagementId,kind,contentHash));
CREATE TABLE commitments (_id TEXT PRIMARY KEY,workspaceId TEXT NOT NULL,engagementId TEXT NOT NULL,documentId TEXT NOT NULL,title TEXT NOT NULL,party TEXT NOT NULL,kind TEXT NOT NULL,amountMinor INTEGER,currency TEXT,dueDate TEXT,conditions TEXT NOT NULL,quote TEXT NOT NULL,quoteStart INTEGER NOT NULL,status TEXT NOT NULL,supersedesId TEXT,itemId TEXT,confidence REAL NOT NULL,createdAt INTEGER NOT NULL,updatedAt INTEGER NOT NULL,UNIQUE(documentId,quoteStart));
CREATE INDEX idx_commitments_workspace ON commitments(workspaceId,engagementId,status);
CREATE TABLE obligationInvoices (_id TEXT PRIMARY KEY,workspaceId TEXT NOT NULL,engagementId TEXT NOT NULL,documentId TEXT,reference TEXT NOT NULL,amountMinor INTEGER NOT NULL CHECK(amountMinor>0),currency TEXT NOT NULL,dueDate TEXT,state TEXT NOT NULL,createdAt INTEGER NOT NULL,UNIQUE(engagementId,reference));
CREATE TABLE obligationPayments (_id TEXT PRIMARY KEY,workspaceId TEXT NOT NULL,engagementId TEXT NOT NULL,reference TEXT NOT NULL,amountMinor INTEGER NOT NULL CHECK(amountMinor>0),currency TEXT NOT NULL,date TEXT NOT NULL,kind TEXT NOT NULL,receiptId TEXT,itemId TEXT NOT NULL,createdAt INTEGER NOT NULL,UNIQUE(engagementId,reference));
CREATE TABLE paymentAllocations (_id TEXT PRIMARY KEY,workspaceId TEXT NOT NULL,paymentId TEXT NOT NULL,invoiceId TEXT NOT NULL,amountMinor INTEGER NOT NULL CHECK(amountMinor>0),UNIQUE(paymentId,invoiceId));
CREATE TABLE obligationFollowups (_id TEXT PRIMARY KEY,workspaceId TEXT NOT NULL,engagementId TEXT NOT NULL,exceptionKey TEXT NOT NULL,itemId TEXT NOT NULL,UNIQUE(workspaceId,exceptionKey));
